LANGUAGES={'ko':('KO','한국어','ko_KR'),'en':('EN','English','en_US'),'ja':('JA','日本語','ja_JP'),'es':('ES','Español','es_ES')}
ABOUT={
 'ja':['DRA9ON CINEMAは、AIを用いて韓国発のオリジナルドラマとジャンル映画を制作するチャンネルです。','韓国AI映画監督協会（KAIFD）特別会員','モーショングラフィックスの経験を土台に、企画、脚本、キャラクター設計、絵コンテ、演出、編集まで、一人の作り手の視点で作品を完成させています。','代表作『FALL 707: REBOOT』は、現代の特殊部隊員が朝鮮王朝の時代に迷い込むミリタリー・ファンタジー。時代劇、アクション、オカルトを横断する物語を届けます。','現代の戦術と朝鮮王朝の世界が出会うとき、見慣れた時代劇に異質な緊張が生まれる。FALL 707は、異なる時代とジャンルの衝突を通して、韓国の物語表現の新たな可能性を探るシリーズです。'],
 'es':['DRA9ON CINEMA es un canal de dramas coreanos originales y cine de género creado con inteligencia artificial.','Miembro especial de la Asociación Coreana de Directores de Cine con IA (KAIFD).','Con una trayectoria en diseño de motion graphics, una sola mirada creativa guía cada proyecto: concepto, guion, personajes, storyboard, dirección y montaje.','Su serie principal, FALL 707: REBOOT, sigue a una capitana de fuerzas especiales que llega a la Corea de la dinastía Joseon. Un universo donde se cruzan la acción militar, la fantasía histórica y lo sobrenatural.','FALL 707 nace del encuentro entre las tácticas modernas y el mundo de Joseon. El choque de épocas y géneros transforma un escenario histórico familiar en una historia de tensión e imaginación, explorando nuevas formas de narrar con cine creado con IA.']}
SEASONS={
 'ja':[
  ('現代の戦術、朝鮮王朝の闇。時代を越えた兵士の、生き残るための戦いが始まる。','707特殊任務部隊のミン・ソア大尉は、朝鮮王朝の宮殿に落下する。イソ王子との出会いをきっかけに、使い慣れた武器だけでは説明できない脅威に直面する。黒い鈴が響く夜、見知らぬ時代の人々とともに生き延びる道を探す。'),
  ('救うはずの仲間が、敵となって帰ってきた。それでも、彼らを置いては帰れない。','朝鮮に来て三か月。冬のモクポジンで暮らすミン・ソアとヨンファの穏やかな日々は、長くは続かなかった。城内への侵入者、そして再び響く不気味な鈴。仲間を捜し、ヨンファを守るため、大尉はこれまでの戦いの常識を越えていく。')],
 'es':[
  ('Tácticas modernas. Oscuridad en Joseon. Una soldado atrapada en otra época lucha por sobrevivir.','La capitana Min Seo-a, de la Unidad de Misiones Especiales 707, cae en los jardines de un palacio de Joseon. Su encuentro con el príncipe Iseo la enfrenta a una amenaza que sus armas no pueden explicar. Cuando una campana negra rompe la noche, deberá confiar en los habitantes de ese mundo para sobrevivir.'),
  ('Las personas que vino a rescatar se han convertido en sus enemigos. Aun así, no puede abandonarlas.','Tras tres meses en Joseon, Min Seo-a encuentra una frágil calma junto a Yeonhwa en el invierno de Mokpojin. Una infiltración y el sonido de una campana sobrenatural vuelven a quebrarla. Para proteger a Yeonhwa y encontrar a sus compañeros, Min tendrá que luchar más allá de todo lo que conoce.')]
}
WORKS={
 'oMJ0hhHa9RQ':{'ja': ('家に連れて帰って · Part 2', '終わらせるべき戦い。帰るべき家。漢陽を取り囲む闇の中、ミン・ソア大尉と仲間たちは退けない戦いを続ける。シーズン3第4話・後編。'), 'es': ('Llévame a casa · Parte 2', 'Una lucha que debe terminar. Un hogar al que volver. La capitana Min Seo-a y sus compañeros se enfrentan a la oscuridad que rodea Hanyang. Temporada 3, episodio 4, parte 2.')},
 '_K7G-_2d_EE':{'ja':('最後の一発 · Part 1','都に迫る闇を前に、ミン・ソア大尉と仲間たちは決死の戦いに挑む。シーズン3第4話・前編。'),'es':('La última bala · Parte 1','Mientras la oscuridad se cierne sobre la capital, la capitana Min Seo-a y sus compañeros afrontan una batalla desesperada. Temporada 3, episodio 4, parte 1.')},
 'DC9wgel53Jk':{'ja':('ソウルが目覚めた','私兵が屋敷を取り囲む夜。ミン大尉と仲間たちは、刃を前にしても退かない。朝鮮と現代のソウル。異なる時代に、同じ夜が訪れる。'),'es':('Seúl despierta','Los soldados privados rodean la mansión. Min y sus compañeros se niegan a retroceder ante las espadas. La misma noche llega a Joseon y al Seúl del presente.')},
 'S1v3yFoAK5w':{
  'ja':('退くな','禁じられた扉の先へ。ミン・ソア大尉は、帰らぬハン軍曹を捜して、さらに深い地下へと進む。罠と闇が行く手を阻む一方、屋敷では彼女の帰りを待つ人々がいた。'),
  'es':('No retrocedas','Tras cruzar la puerta prohibida, la capitana Min Seo-a desciende aún más en busca del sargento Han. Mientras las trampas y la oscuridad le cierran el paso, en la mansión esperan su regreso.')},
 '0I75_YXhMSM':{
  'ja':('禁じられた扉を、彼女は開いた','あの夜から半年。かりそめの平穏の中、キム軍曹に異変が現れ始める。ハン軍曹は今も行方不明。仲間を捜すミン・ソア大尉の前に、隠された道と、決して開けるなと告げられた扉が現れる。'),
  'es':('Le advirtieron que no abriera la puerta. Ella entró.','Seis meses después de aquella noche, una paz frágil se rompe cuando el sargento Kim empieza a mostrar síntomas inquietantes. El sargento Han sigue desaparecido. Para encontrar a su compañero, la capitana Min Seo-a deberá enfrentarse a un camino oculto y una puerta prohibida.')},
 'sFw17ZPE42A':{'ja':('彼らを置いては帰れない · シーズン2 一挙上映','救うために来た仲間が、今は彼女に襲いかかる。朝鮮王朝の闇と黒い鈴の謎に挑むミン大尉の物語。シーズン2の第1話から第6話までを一本で。'),'es':('No puedo dejarlos atrás · Temporada 2 completa','Vino a salvar a sus compañeros. Ahora ellos la atacan. Acompaña a Min a través de la oscuridad de Joseon y el misterio de la campana negra. Los seis episodios de la segunda temporada en una sola película.')},
 'F-MEc4hmxJU':{'ja':('終わったと思った？ · シーズン2 最終話','仲間を救えば、すべてが終わると思っていた。だが、彼らを縛る手はまだ離れていない。シーズン2最終話、ミン大尉は指揮官として残酷な選択を迫られる。'),'es':('¿Pensaste que había terminado? · Final de temporada 2','Creía que rescatar a sus compañeros pondría fin a todo. Pero la fuerza que los retiene aún no los ha soltado. En el final de temporada, Min afronta una elección que ningún comandante debería tener que hacer.')},
 '6Wdj9n3Pq9Q':{'ja':('ミン大尉が倒れた、その時','尽きることのない敵。傷つき、一人で戦うミン大尉。その戦場に、新たな力が現れようとしていた。シーズン2、第5話。'),'es':('Cuando cae la capitana Min','Una horda interminable. Una capitana herida que sigue luchando sola. Una nueva fuerza está a punto de entrar en la batalla. Temporada 2, episodio 5.')},
 'bDqEJXYr2dY':{'ja':('すべて知っていたはずだ','ヨンファを救うため、仮面の王子が現れる。だが、大尉の仲間たちは再び奪われてしまう。救ってくれた相手に向けられる銃口。シーズン2、第4話。'),'es':('Lo sabías todo','Un príncipe enmascarado llega para rescatar a Yeonhwa, pero los compañeros de Min vuelven a ser capturados. La capitana apunta su arma hacia quien acaba de salvarla. Temporada 2, episodio 4.')},
 'vrVGZ_HMxQs':{'ja':('撃てない敵','ヨンファが連れ去られ、かつての仲間が敵として立ちはだかる。それでも、大尉は救出を諦めない。シーズン2、第3話。'),'es':('El enemigo al que no puedo disparar','Yeonhwa ha sido secuestrada y antiguos compañeros se han convertido en enemigos. Min no está dispuesta a renunciar al rescate. Temporada 2, episodio 3.')},
 'dGnjxL64HHY':{'ja':('モクポジンの夜 · シーズン2 第1・2話','冬のモクポジンで生まれた静かな絆は、城内を襲う侵入者と不気味な鈴の音に揺さぶられる。シーズン2の第1・2話を連続で。'),'es':('Una noche en Mokpojin · Temporada 2, episodios 1 y 2','Un vínculo nacido en el invierno de Mokpojin se ve amenazado por una infiltración y el sonido de una campana inquietante. Los dos primeros episodios de la segunda temporada, sin interrupciones.')},
 'WZ0ozLABZwE':{'ja':('モクポジン襲撃の夜','冬の深夜、覆面の侵入者たちがモクポジンの城壁を越える。警備も通路も知り尽くした襲撃。その背後で、異様な鈴が鳴り始める。'),'es':('La noche del asalto a Mokpojin','En plena noche de invierno, decenas de intrusos enmascarados cruzan las murallas de Mokpojin. Conocen cada guardia y cada acceso. Entonces empieza a sonar una campana que no pertenece a este mundo.')},
 'l2G5ITnriFQ':{'ja':('雪道で結ばれた縁','朝鮮に来て三か月。修理したオートバイで雪道を走るミン・ソア大尉は、知るはずのないことを知る人物と出会う。まだ始まらぬ戦いを前に、ひとつの縁が結ばれる。'),'es':('Un encuentro en el camino nevado','Tres meses en Joseon. La capitana Min Seo-a recorre un camino nevado en una motocicleta reconstruida. Un encuentro con alguien que sabe demasiado da lugar a un vínculo inesperado, antes de una guerra que aún no ha comenzado.')},
 '4f6Zguf7c2M':{'ja':('FALL 707 · シーズン1 一挙上映','現代の特殊部隊員が、朝鮮王朝の宮殿に落下する。異なる時代の出会い、黒い鈴の不穏な響き、そして生き残るための戦い。シーズン1全6話を一本で。'),'es':('FALL 707 · Temporada 1 completa','Una capitana de fuerzas especiales cae en un palacio de la dinastía Joseon. Encuentros entre épocas, una campana negra y una lucha por sobrevivir. Los seis episodios de la primera temporada, reunidos en una sola película.')},
 'BY0ZT5SK8qY':{'ja':('宮殿、最後の夜','宮殿を包み込む闇。人々を守るため、ミン大尉とイソは最後の戦いへ向かう。シーズン1最終話。'),'es':('La última noche del palacio','La oscuridad envuelve el palacio. Min e Iseo se preparan para una última batalla para proteger a su gente. Final de la primera temporada.')},
 'hoFQL2ON9m4':{'ja':('宮殿、最後の夜 · 予告編','黒い鈴の謎を追う先で、宮殿に不穏な闇が迫る。現代の銃撃と超常の力がぶつかる、シーズン1最終話の予告編。'),'es':('La última noche del palacio · Tráiler','El misterio de la campana negra conduce hacia una oscuridad que amenaza el palacio. Armas modernas y fuerzas sobrenaturales se enfrentan en el tráiler del final de la primera temporada.')},
 '6CCZA8el6Mk':{'ja':('宮殿に響く銃声','宮殿に迫る脅威を前に、現代の装備と朝鮮王朝の世界が交差する。ミン大尉は目の前の人々を守るため銃を取る。シーズン1、第5話。'),'es':('Disparos en el palacio','Ante la amenaza que se aproxima, las armas modernas y el mundo de Joseon se encuentran. Min toma su rifle para proteger a quienes la rodean. Temporada 1, episodio 5.')},
 'gTdqOtFvcDM':{'ja':('黒い鈴','静寂を破る鈴の音。その響きが、朝鮮の夜に隠されていた脅威を呼び覚ます。シーズン1、第4話。'),'es':('La campana negra','Un sonido rompe el silencio. Su eco despierta una amenaza oculta en la noche de Joseon. Temporada 1, episodio 4.')},
 'HP-B3jZLs3w':{'ja':('再び立ち上がる者たち','見知らぬ時代で生き延びようとする大尉。その前に現れたのは、常識では説明できない者たちだった。シーズン1、第3話。'),'es':('Los que vuelven a levantarse','La capitana intenta sobrevivir en una época desconocida. Pero se enfrenta a seres que desafían todo lo que creía posible. Temporada 1, episodio 3.')},
 'NV9PeKvKv7c':{'ja':('朝鮮で目を覚ました707大尉','意識を取り戻した場所は、現代ではなかった。707特殊任務部隊の大尉と、朝鮮の王子イソ。時代を越えた出会いが物語を動かす。'),'es':('Una capitana del 707 despierta en Joseon','Cuando recobra la conciencia, el presente ha desaparecido. Una capitana de la Unidad 707 y el príncipe Iseo se encuentran en un mundo separado por siglos. Ese encuentro lo cambiará todo.')},
 'y4t5NDVqPyU':{'ja':('爆発の中に消えた707大尉','現代の作戦現場。突然の爆発が、ミン・ソア大尉の運命を変える。朝鮮王朝へと続く物語、その始まり。'),'es':('La capitana del 707 desaparece entre las llamas','Una misión en el presente. Una explosión inesperada cambia el destino de la capitana Min Seo-a. Así comienza su viaje hacia la dinastía Joseon.')},
 'BwOk1ZoKJnE':{'ja':('FALL 707 · シーズン1・2 ボーカルOST集','シーズン1・2の映像とともに聴く、13曲のボーカルOST。完成版に使われなかった未公開のAI生成カットも収録。'),'es':('FALL 707 · Banda sonora vocal de las temporadas 1 y 2','Trece canciones con escenas de las dos primeras temporadas, incluidos planos generados con IA que no llegaron a las versiones finales.')},
}
